cd /app && cat .gnomon-jobs/pypi.log; echo "=== pidfile:"; cat .gnomon-jobs/pypi.pid 2>/dev/null; echo "=== which process listens on 8080:"; python3 - <<'EOF'
import os, glob, re
# decode listeners from /proc/net/tcp (+tcp6)
inodes=set()
for f in ("/proc/net/tcp","/proc/net/tcp6"):
    try: lines=open(f).read().splitlines()[1:]
    except FileNotFoundError: continue
    for l in lines:
        p=l.split()
        if p[3]=="0A":  # LISTEN
            port=int(p[1].split(":")[1],16)
            if port==8080: inodes.add(p[9])
print("listen inodes:", inodes)
for fd in glob.glob("/proc/[0-9]*/fd/*"):
    try: t=os.readlink(fd)
    except OSError: continue
    m=re.match(r"socket:\[(\d+)\]",t)
    if m and m.group(1) in inodes:
        pid=fd.split("/")[2]
        try: cmd=open("/proc/%s/cmdline"%pid).read().replace("\0"," ").strip()
        except OSError: cmd="?"
        print("pid",pid,"->",cmd)
EOF
